update public.blog_posts set content = replace(content, 'Contractele primesc numere pe fiecare an și tip și stau într-o listă comună.', 'Pentru contractele de comision, vizionare și reprezentare exclusivă, fiecare agenție își alege seria și numărul de start pe tip de contract, iar contractele de închiriere și comodat nu au număr pe document. Toate contractele stau într-o listă comună.') where content like '%numere pe fiecare an%';